def solve(p1, p2, n):
    # Давление насыщенного пара ps находится из условия: p1 = n_газ-часть + ps, после двукратного расширения p2 = (p1 - ps)/2 + ps
    ps = 2*p2 - p1
    T = [273, 283, 293, 303, 313, 323, 333, 343, 353, 363, 373]
    P = [0.00603, 0.0121, 0.0230, 0.0418, 0.0728, 0.1217, 0.1966, 0.3075, 0.467, 0.692, 1.0]
    for i in range(len(T) - 1):
        if P[i] <= ps <= P[i + 1]:
            return T[i] + (T[i + 1] - T[i]) * (ps - P[i]) / (P[i + 1] - P[i])
    return -1
